input.command:
python3 - <<'EOF'
import re, subprocess

files = subprocess.run(["grep","-rln","tasklet_init\\|DECLARE_TASKLET\\|netif_napi_add\\|NAPI_POLL\\|napi_schedule","--include=*.c","drivers/net/","drivers/staging/","net/","drivers/char/","drivers/block/","drivers/atm/","drivers/crypto/","drivers/tty/","drivers/usb/","drivers/infiniband/"],capture_output=True,text=True).stdout.split()
print("files:", len(files))

def parse_functions(src):
    funcs = []
    lines = src.split('\n')
    i = 0; n = len(lines)
    while i < n:
        m = re.match(r'^([A-Za-z_][A-Za-z0-9_]*)\s*\(', lines[i])
        if m:
            k = i; started = False
            while k < n and k < i + 12:
                if '{' in lines[k]: started = True; break
                if lines[k].rstrip().endswith(';'): break
                k += 1
            if started:
                depth = 0; end = None
                for k2 in range(k, n):
                    depth += lines[k2].count('{') - lines[k2].count('}')
                    if depth == 0:
                        end = k2; break
                if end is not None:
                    funcs.append((m.group(1), i+1, end+1, '\n'.join(lines[i:end+1])))
                    i = end + 1; continue
        i += 1
    return funcs

LOCK_RE = re.compile(r'(spin_lock\w*)\s*\(\s*&?\s*([A-Za-z0-9_\.\->\[\]\(\)]+?)\s*[,)]')

for f in files:
    try: src = open(f).read()
    except: continue
    softirq_fns = set()
    for m in re.finditer(r'tasklet_init\s*\(\s*&[^,]+,\s*([A-Za-z0-9_]+)\s*,', src):
        softirq_fns.add(m.group(1))
    for m in re.finditer(r'DECLARE_TASKLET[^;]*?\(\s*[^,]+,\s*([A-Za-z0-9_]+)\s*,', src):
        softirq_fns.add(m.group(1))
    # napi poll fns - positional 3rd arg typically
    for m in re.finditer(r'netif_napi_add(?:_compat)?\s*\(([^;]*?)\)\s*;', src, re.S):
        args = [a.strip() for a in m.group(1).split(',')]
        if len(args) >= 3:
            poll = args[2].strip()
            mm = re.match(r'^&?([A-Za-z0-9_]+)$', poll)
            if mm: softirq_fns.add(mm.group(1))
    if not softirq_fns: continue
    funcs = parse_functions(src)
    fmap = {n:(sl,el,body) for (n,sl,el,body) in funcs}
    for fn in list(softirq_fns):
        if fn not in fmap:
            softirq_fns.discard(fn)

    # collect lock usages per function
    fn_locks = {}  # fn -> list of (variant, lock, line)
    for (name, sl, el, body) in funcs:
        if name in softirq_fns or True:
            for m in LOCK_RE.finditer(body):
                fn_locks.setdefault(name, []).append((m.group(1), m.group(2), sl + body[:m.start()].count('\n')))

    # plain spin_lock in non-softirq functions
    plain = {}
    for fn, lst in fn_locks.items():
        if fn in softirq_fns: continue
        for (v, lock, line) in lst:
            if v == 'spin_lock':
                plain.setdefault(lock, []).append((fn, line))

    if not plain: continue
    # softirq-side locks (any variant) — check overlap
    for fn in softirq_fns:
        for (v, lock, line) in fn_locks.get(fn, []):
            base = lock.split('->')[-1].split('.')[-1]
            for plock, sites in plain.items():
                pbase = plock.split('->')[-1].split('.')[-1]
                if pbase == base and base not in ('lock','') and len(base) > 3:
                    print(f"{f} :: SOFTIRQ {fn}:{line} {v}({lock})  <-> PLAIN {sites[:3]}")
EOF

